38	export function toggleTaskAtLine(markdown: string, lineNumber: number, checked: boolean): string {
39	  const lines = markdown.split("\n");
40	
41	  if (lineNumber < 0 || lineNumber >= lines.length) {
42	    return markdown;
43	  }
44	
45	  const line = lines[lineNumber];
46	
47	  // Match task list patterns: - [ ], - [x], - [X], etc.
48	  const taskPattern = /^(\s*[-*+]\s+)\[([ xX])\](\s+.*)$/;
49	  const match = line.match(taskPattern);
50	
51	  if (!match) {
52	    return markdown;
53	  }
54	
55	  const [, prefix, , suffix] = match;
56	  const newCheckmark = checked ? "x" : " ";
57	  lines[lineNumber] = `${prefix}[${newCheckmark}]${suffix}`;
58	
59	  return lines.join("\n");
60	}
